Rails.application.config.assets.paths << ManageIQ::UI::Classic::Engine.root.join('node_modules')

Rails.application.config.assets.precompile << proc do |filename, path|
  path =~ %r{app/assets} && !%w(.js .css .sass).include?(File.extname(filename))
end

# Generated by rake locale:compile into app/assets/locale, which Rails adds as an
# asset root, so these are served as e.g. /assets/ja-<digest>.js
Rails.application.config.assets.precompile << proc do |_logical_path, path|
  path.to_s.start_with?(ManageIQ::UI::Classic::Engine.root.join('app', 'assets', 'locale').to_s) && File.extname(path) == '.js'
end
